    # A hollow box: rectangular border of same color, interior is different/empty

    def is_frame(r1, c1, r2, c2, color):
        # Check if top and bottom rows are all color
        for c in range(c1, c2 + 1):
            if grid[r1][c] != color:
                return False
            if grid[r2][c] != color:
                return False
        # Check left and right columns
        for r in range(r1, r2 + 1):
            if grid[r][c1] != color:
                return False
            if grid[r][c2] != color:
                return False
        return True

    # Find minimal bounding box around each connected component of a color
    found = set()

    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color in found:
                continue

            # BFS flood fill to find extent of this connected component
            Q = [(r, c)]
            visited = [[False]*cols for _ in range(rows)]
            visited[r][c] = True
            bounds = {'min_r': r, 'max_r': r, 'min_c': c, 'max_c': c}

            while Q:
                cr, cc = Q.pop()
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if not visited[nr][nc] and grid[nr][nc] == color:
                            visited[nr][nc] = True
                            Q.append((nr, nc))
                            bounds['min_r'] = min(bounds['min_r'], nr)
                            bounds['max_r'] = max(bounds['max_r'], nr)
                            bounds['min_c'] = min(bounds['min_c'], nc)
                            bounds['max_c'] = max(bounds['max_c'], nc)

            # Check if this component forms a hollow frame
            if bounds['max_r'] - bounds['min_r'] + 1 >= 2 and bounds['max_c'] - bounds['min_c'] + 1 >= 2:
                if is_frame(bounds['min_r'], bounds['min_c'], bounds['max_r'], bounds['max_c'], color):
                    # Only change if interior is not the same color (it's a frame, not solid)
                    interior_char = grid[bounds['min_r'] + 1][bounds['min_c'] + 1] if bounds['max_r'] - bounds['min_r'] > 1 and bounds['max_c'] - bounds['min_c'] > 1 else color
